SELECT $j$sa-dec-flower-half-marathon-2026-runner-va-hoa$j$, 'article', 'tin-tuc', $j$Runner & Hoa – khi bước chạy hòa cùng sắc hoa Sa Đéc$j$, $j$Runner & Hoa là hoạt động hưởng ứng Sa Đéc Flower Half Marathon 2026 (25–27/12/2026), kết nối người yêu chạy bộ với hoa kiểng Sa Đéc: chạy qua cung đường hoa, check-in bên vườn hoa và gặp gỡ người trồng hoa.$j$,
  $j$[{"type": "p", "text": "Có những cung đường để chinh phục giới hạn. Có những cung đường để tận hưởng vẻ đẹp thiên nhiên. Và tại **Sa Đéc Flower Half Marathon 2026**, mỗi bước chạy còn là một hành trình khám phá sắc màu của Phố hoa!"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__4__8be50b0f33544fef868a6fb31a6f160d.webp", "caption": "Cung đường 5 km đi xuyên Làng hoa Sa Đéc – nơi diễn ra nhiều khoảnh khắc “Runner & Hoa” (ảnh: Ban tổ chức)"}, {"type": "h2", "text": "🌷 Runner & Hoa là gì?"}, {"type": "p", "text": "**Runner & Hoa** là hoạt động kết nối những người yêu chạy bộ với vẻ đẹp của hoa kiểng Sa Đéc. Các runner không chỉ chạy qua những cung đường rực rỡ sắc hoa mà còn có cơ hội:"}, {"type": "list", "ordered": false, "items": ["Lưu giữ khoảnh khắc đáng nhớ bên những vườn hoa.", "Gặp gỡ những người trồng hoa – những người đã gắn bó cả đời với nghề.", "Cảm nhận nhịp sống bình dị, hiếu khách của người dân địa phương."]}, {"type": "h2", "text": "🌹 Chạy giữa muôn hoa – chạm vào cảm xúc"}, {"type": "p", "text": "Mỗi bức ảnh là một kỷ niệm. Mỗi bước chân là một trải nghiệm. Và mỗi runner sẽ trở thành một **đại sứ lan tỏa vẻ đẹp của Sa Đéc** đến bạn bè khắp mọi miền."}, {"type": "p", "text": "Hãy cùng biến những cung đường hoa thành nơi hội tụ của **thể thao, thiên nhiên, văn hóa và những nụ cười**!"}, {"type": "note", "title": "Mẹo chụp ảnh đẹp từ nhà vườn", "text": "Cuối tháng 12 là mùa hoa Tết: cúc mâm xôi, vạn thọ, hồng, giấy… đang nở rộ. Ảnh đẹp nhất vào sáng sớm khi nắng xiên. Xin phép chủ vườn trước khi vào sát luống hoa và không giẫm lên chậu hoa nhé."}, {"type": "h2", "text": "Thông tin giải"}, {"type": "table", "rows": [["Sự kiện", "Sa Đéc Flower Half Marathon 2026"], ["Chủ đề", "Chinh phục cung đường hoa"], ["Thời gian", "25–27/12/2026"], ["Địa điểm", "Phường Sa Đéc, tỉnh Đồng Tháp"]]}, {"type": "p", "text": "Hashtag: #RunnerVaHoa #SaDecFlowerHalfMarathon2026 #ChinhPhucCungDuongHoa #PhoHoaSaDec #RunForABrighterSaDec"}, {"type": "h2", "text": "Đọc thêm về giải chạy"}, {"type": "list", "ordered": false, "items": ["[Lộ trình chi tiết 5 km, 10 km, 21 km và sơ đồ Expo](/tin-tuc/sa-dec-flower-half-marathon-2026-lo-trinh)", "[Bộ racekit, bảng size áo và giá vé](/tin-tuc/sa-dec-flower-half-marathon-2026-racekit-gia-ve)"]}, {"type": "p", "text": "Về Sa Đéc dịp giải chạy, mời bạn ghé vườn Cây Cảnh Miền Tây tại Làng hoa Sa Đéc – xem [hệ thống cửa hàng](/he-thong-cua-hang)."}]$j$::jsonb, $j$https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__4__8be50b0f33544fef868a6fb31a6f160d.webp$j$, 3, 'Cây Cảnh Miền Tây',
  '[]'::jsonb, $j$["Runner & Hoa", "Sa Đéc Flower Half Marathon", "Phố hoa Sa Đéc"]$j$::jsonb, $j$Runner & Hoa – hoạt động hưởng ứng Sa Đéc Flower Half Marathon 2026: chạy giữa vườn hoa, check-in, gặp người trồng hoa Làng hoa Sa Đéc.$j$,
  'published', '2026-11-11 13:50:00+07'::timestamptz, 'Hệ thống'
WHERE NOT EXISTS (SELECT 1 FROM "posts" x WHERE x."slug" = $j$sa-dec-flower-half-marathon-2026-runner-va-hoa$j$);
