SELECT $j$sa-dec-flower-half-marathon-2026-cosplay-sac-hoa$j$, 'article', 'tin-tuc', $j$Cosplay “Rực rỡ sắc hoa Sa Đéc” – khi những đóa hoa bước ra phố$j$, $j$Hoạt động Cosplay “Rực rỡ sắc hoa Sa Đéc” trong Sa Đéc Flower Half Marathon 2026 mời runner hóa thân thành hoa hồng, hướng dương, hoa cúc hay nhân vật cổ tích, biến cung đường hoa thành lễ hội sắc màu.$j$,
  $j$[{"type": "p", "text": "Khi những đóa hoa bước ra phố, cùng các runner tạo nên một **lễ hội sắc màu**! Bạn đã bao giờ tưởng tượng mình hóa thân thành một đóa hồng kiêu sa, một bông hướng dương rực rỡ hay một nhân vật đầy sáng tạo lấy cảm hứng từ thế giới hoa chưa?"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png", "caption": "Sa Đéc Flower Half Marathon 2026 – Chinh phục cung đường hoa (ảnh: Ban tổ chức)"}, {"type": "h2", "text": "🌷 Thể thao hòa quyện cùng nghệ thuật"}, {"type": "p", "text": "Trong khuôn khổ Sa Đéc Flower Half Marathon 2026, hoạt động **“Cosplay – Rực rỡ sắc hoa Sa Đéc”** mang đến một không gian đầy màu sắc, nơi thể thao hòa quyện cùng nghệ thuật, thời trang và vẻ đẹp đặc trưng của Phố hoa Sa Đéc."}, {"type": "h2", "text": "🌺 Gợi ý ý tưởng hóa trang"}, {"type": "list", "ordered": false, "items": ["Trang phục lấy cảm hứng từ **hoa hồng** – biểu tượng của logo giải.", "**Hoa cúc, hoa hướng dương** – rực rỡ sắc vàng mùa Tết.", "**Nhân vật cổ tích** và những tạo hình độc đáo mang hơi thở thiên nhiên."]}, {"type": "p", "text": "Không chỉ là hóa trang, đây còn là dịp để mỗi người **thể hiện cá tính, sức sáng tạo và tình yêu dành cho hoa Sa Đéc**. Hãy để những bước chân thêm rực rỡ, những nụ cười thêm tươi vui và mỗi khoảnh khắc trở thành một kỷ niệm khó quên!"}, {"type": "note", "title": "Lưu ý khi chạy cùng trang phục", "text": "Chọn chất liệu nhẹ, thoáng, không che tầm nhìn và không vướng chân; tránh phụ kiện cứng, sắc nhọn. Mặc thử và chạy thử vài km trước ngày thi đấu. BIB phải đeo phía trước, nhìn thấy rõ."}, {"type": "p", "text": "💚 Sa Đéc không chỉ có những mùa hoa nở, mà còn có những con người cùng nhau làm nên một mùa hoa thật đặc biệt!"}, {"type": "h2", "text": "Thông tin giải"}, {"type": "table", "rows": [["Sự kiện", "Sa Đéc Flower Half Marathon 2026"], ["Chủ đề", "Chinh phục cung đường hoa"], ["Thời gian", "25–27/12/2026"], ["Địa điểm", "Phường Sa Đéc, tỉnh Đồng Tháp"]]}, {"type": "p", "text": "Hashtag: #CosplayRucRoSacHoa #SaDecFlowerHalfMarathon2026 #ChinhPhucCungDuongHoa #PhoHoaSaDec #RunForABrighterSaDec"}, {"type": "h2", "text": "Đọc thêm về giải chạy"}, {"type": "list", "ordered": false, "items": ["[Lộ trình chi tiết 5 km, 10 km, 21 km và sơ đồ Expo](/tin-tuc/sa-dec-flower-half-marathon-2026-lo-trinh)", "[Bộ racekit, bảng size áo và giá vé](/tin-tuc/sa-dec-flower-half-marathon-2026-racekit-gia-ve)"]}, {"type": "p", "text": "Về Sa Đéc dịp giải chạy, mời bạn ghé vườn Cây Cảnh Miền Tây tại Làng hoa Sa Đéc – xem [hệ thống cửa hàng](/he-thong-cua-hang)."}]$j$::jsonb, $j$https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png$j$, 3, 'Cây Cảnh Miền Tây',
  '[]'::jsonb, $j$["Cosplay", "Sa Đéc Flower Half Marathon", "Phố hoa Sa Đéc"]$j$::jsonb, $j$Cosplay Rực rỡ sắc hoa Sa Đéc – runner hóa trang hoa hồng, hướng dương, cúc tại Sa Đéc Flower Half Marathon 2026 (25–27/12/2026).$j$,
  'published', '2026-11-11 13:52:00+07'::timestamptz, 'Hệ thống'
WHERE NOT EXISTS (SELECT 1 FROM "posts" x WHERE x."slug" = $j$sa-dec-flower-half-marathon-2026-cosplay-sac-hoa$j$);
