SELECT $j$sa-dec-flower-half-marathon-2026-am-thuc-xu-hoa$j$, 'article', 'tin-tuc', $j$Ẩm thực Xứ hoa Sa Đéc – đậm đà hương vị miền Tây$j$, $j$Liên hoan “Ẩm thực Xứ hoa Sa Đéc” trong Sa Đéc Flower Half Marathon 2026 giới thiệu hủ tiếu Sa Đéc, bánh dân gian và món ngon sông nước tại khu Làng bột Sa Đéc và “Chợ quê lên phố” cạnh Expo.$j$,
  $j$[{"type": "p", "text": "Đến Sa Đéc không chỉ để ngắm hoa, chạy giữa những cung đường hoa, mà còn để thưởng thức những hương vị đặc trưng của **vùng đất trăm năm**!"}, {"type": "h2", "text": "🌷 Không gian văn hóa ẩm thực đặc sắc"}, {"type": "p", "text": "Trong khuôn khổ Sa Đéc Flower Half Marathon 2026, hoạt động **“Ẩm thực Xứ hoa Sa Đéc”** mang đến không gian trải nghiệm văn hóa ẩm thực, nơi hội tụ những món ngon dân dã, hương vị truyền thống và tinh hoa ẩm thực của vùng đất Đồng Tháp."}, {"type": "h2", "text": "🍜 Những món nên thử"}, {"type": "list", "ordered": false, "items": ["**Hủ tiếu Sa Đéc** trứ danh với sợi bánh dai mềm đặc trưng.", "**Bánh dân gian** thơm ngon từ làng bột Sa Đéc.", "Các **món ăn đậm chất sông nước** miền Tây.", "**Sản phẩm OCOP và đặc sản** địa phương làm quà."]}, {"type": "p", "text": "Giữa muôn sắc hoa, thưởng thức một món ngon cũng là cách để **cảm nhận Sa Đéc bằng tất cả giác quan**. Đây còn là dịp giới thiệu sản phẩm đặc trưng địa phương, tôn vinh bàn tay khéo léo của người làm nghề và kết nối du khách với văn hóa bản địa."}, {"type": "h2", "text": "📍 Ăn ở đâu trong khu Expo?"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__5__71579536835941a3961fa2cb57df84c5.jpg", "caption": "Sơ đồ khu Expo: khu ẩm thực Làng bột Sa Đéc (gian 1–10) và “Chợ quê lên phố” (gian 11–20) (ảnh: Ban tổ chức)"}, {"type": "list", "ordered": false, "items": ["**Khu ẩm thực Làng bột Sa Đéc** – 10 gian (số 1–10), cạnh khu nhận BIB.", "**Khu ẩm thực địa phương “Chợ quê lên phố”** – 10 gian (số 11–20).", "**Không gian OCOP và đặc sản địa phương** trong nhà Expo.", "Có **khu bàn ghế ngồi**, sân khấu và bãi đậu xe ngay bên cạnh."]}, {"type": "p", "text": "💚 Sa Đéc – Nơi sắc hoa làm say lòng người, còn hương vị quê nhà khiến bước chân muốn ở lại!"}, {"type": "h2", "text": "Thông tin giải"}, {"type": "table", "rows": [["Sự kiện", "Sa Đéc Flower Half Marathon 2026"], ["Chủ đề", "Chinh phục cung đường hoa"], ["Thời gian", "25–27/12/2026"], ["Địa điểm", "Phường Sa Đéc, tỉnh Đồng Tháp"]]}, {"type": "p", "text": "Hashtag: #AmThucXuHoaSaDec #SaDecFlowerHalfMarathon2026 #ChinhPhucCungDuongHoa #HuTieuSaDec #PhoHoaSaDec #AmThucDongThap"}, {"type": "h2", "text": "Đọc thêm về giải chạy"}, {"type": "list", "ordered": false, "items": ["[Lộ trình chi tiết 5 km, 10 km, 21 km và sơ đồ Expo](/tin-tuc/sa-dec-flower-half-marathon-2026-lo-trinh)", "[Bộ racekit, bảng size áo và giá vé](/tin-tuc/sa-dec-flower-half-marathon-2026-racekit-gia-ve)"]}, {"type": "p", "text": "Về Sa Đéc dịp giải chạy, mời bạn ghé vườn Cây Cảnh Miền Tây tại Làng hoa Sa Đéc – xem [hệ thống cửa hàng](/he-thong-cua-hang)."}]$j$::jsonb, $j$https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__5__71579536835941a3961fa2cb57df84c5.jpg$j$, 3, 'Cây Cảnh Miền Tây',
  '[]'::jsonb, $j$["ẩm thực Sa Đéc", "hủ tiếu Sa Đéc", "Sa Đéc Flower Half Marathon"]$j$::jsonb, $j$Ẩm thực Xứ hoa Sa Đéc tại Sa Đéc Flower Half Marathon 2026: hủ tiếu Sa Đéc, bánh dân gian, đặc sản Đồng Tháp, 20 gian ẩm thực cạnh Expo.$j$,
  'published', '2026-11-11 13:54:00+07'::timestamptz, 'Hệ thống'
WHERE NOT EXISTS (SELECT 1 FROM "posts" x WHERE x."slug" = $j$sa-dec-flower-half-marathon-2026-am-thuc-xu-hoa$j$);
