SELECT $j$sa-dec-flower-half-marathon-2026-dem-nhac-soi-dong-mua-hoa-moi$j$, 'article', 'tin-tuc', $j$Đêm nhạc “Sôi động mùa hoa mới” – bùng nổ cảm xúc giữa Phố hoa Sa Đéc$j$, $j$Đêm nhạc tuổi trẻ “Sôi động mùa hoa mới” trong Sa Đéc Flower Half Marathon 2026 (25–27/12/2026) mang đến các tiết mục âm nhạc sôi động, điểm hẹn cho runner, người dân và du khách giữa Phố hoa Sa Đéc.$j$,
  $j$[{"type": "p", "text": "Khi những cung đường hoa rực rỡ sắc màu hòa cùng ánh đèn sân khấu, khi âm nhạc kết nối những trái tim yêu thể thao và những tâm hồn yêu hoa, một **đêm hội đầy cảm xúc** sẽ được thắp sáng tại Sa Đéc!"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png", "caption": "Sa Đéc Flower Half Marathon 2026 – 25–27/12/2026 (ảnh: Ban tổ chức)"}, {"type": "h2", "text": "🎶 Không gian nghệ thuật trẻ trung, sôi động"}, {"type": "p", "text": "Trong khuôn khổ Sa Đéc Flower Half Marathon 2026, đêm nhạc **“Sôi động mùa hoa mới”** hứa hẹn mang đến những giai điệu hiện đại hòa quyện cùng sắc màu văn hóa của vùng đất trăm năm nghề hoa."}, {"type": "list", "ordered": false, "items": ["Những **tiết mục âm nhạc cuồng nhiệt**.", "Những **màn trình diễn đầy năng lượng**.", "Không khí **lễ hội rực rỡ** – điểm hẹn dành cho runner, người dân và du khách."]}, {"type": "h2", "text": "🌹 Lời chào mùa hoa mới"}, {"type": "p", "text": "Không chỉ là một đêm nhạc, đây còn là lời chào đón **một mùa hoa mới, một hành trình mới và những khát vọng mới** của Phố hoa Sa Đéc. Hãy cùng hòa mình vào âm nhạc, kết nối những người bạn mới và tận hưởng những khoảnh khắc đáng nhớ giữa không gian ngập tràn sắc hoa!"}, {"type": "note", "title": "Thời gian và địa điểm cụ thể", "text": "Ban tổ chức chưa công bố giờ và sân khấu chính xác của đêm nhạc. Theo dõi sadecmarathon.com hoặc fanpage SaDecFlowerHalfMarathon để cập nhật. Runner thi đấu sáng hôm sau nhớ về nghỉ sớm!"}, {"type": "p", "text": "💚 Sa Đéc – Nơi hoa khoe sắc, âm nhạc thăng hoa và những trái tim cùng chung nhịp đập!"}, {"type": "h2", "text": "Thông tin giải"}, {"type": "table", "rows": [["Sự kiện", "Sa Đéc Flower Half Marathon 2026"], ["Chủ đề", "Chinh phục cung đường hoa"], ["Thời gian", "25–27/12/2026"], ["Địa điểm", "Phường Sa Đéc, tỉnh Đồng Tháp"]]}, {"type": "p", "text": "Hashtag: #SoiDongMuaHoaMoi #SaDecFlowerHalfMarathon2026 #ChinhPhucCungDuongHoa #PhoHoaSaDec #RunForABrighterSaDec"}, {"type": "h2", "text": "Đọc thêm về giải chạy"}, {"type": "list", "ordered": false, "items": ["[Lộ trình chi tiết 5 km, 10 km, 21 km và sơ đồ Expo](/tin-tuc/sa-dec-flower-half-marathon-2026-lo-trinh)", "[Bộ racekit, bảng size áo và giá vé](/tin-tuc/sa-dec-flower-half-marathon-2026-racekit-gia-ve)"]}, {"type": "p", "text": "Về Sa Đéc dịp giải chạy, mời bạn ghé vườn Cây Cảnh Miền Tây tại Làng hoa Sa Đéc – xem [hệ thống cửa hàng](/he-thong-cua-hang)."}]$j$::jsonb, $j$https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png$j$, 3, 'Cây Cảnh Miền Tây',
  '[]'::jsonb, $j$["đêm nhạc", "Sa Đéc Flower Half Marathon", "Phố hoa Sa Đéc"]$j$::jsonb, $j$Đêm nhạc Sôi động mùa hoa mới – sân khấu âm nhạc tuổi trẻ tại Sa Đéc Flower Half Marathon 2026, 25–27/12/2026, phường Sa Đéc.$j$,
